class External:
    def __init__(self):
        self.records = []
    def create(self, payload):
        record = {'id': 101 + len(self.records), 'payload': payload}
        self.records.append(record)
        return record

class Checkpoints:
    def __init__(self, crash_once=False):
        self.results = {}
        self.crash_once = crash_once
    def done(self, action_id):
        return action_id in self.results
    def complete(self, action_id, result):
        if self.crash_once:
            self.crash_once = False
            raise RuntimeError('simulated crash before checkpoint persistence')
        self.results[action_id] = result

